import pandas as pd
import numpy as np

# Define the indicators
def calculate_bollinger_bands(data, period, std_dev):
  sma = data['close'].rolling(window=period).mean()
  std = data['close'].rolling(window=period).std()
  upper_bb = sma + std_dev * std
  lower_bb = sma - std_dev * std
  return upper_bb, lower_bb

def calculate_cci(data, period):
  tp = (data['high'] + data['low'] + data['close']) / 3
  cci = (tp - tp.rolling(window=period).mean()) / (0.015 * tp.rolling(window=period).std())
  return cci

# Define the strategy
class SupportResistanceStrategy:
  def __init__(self, data):
    self.data = data
    self.upper_bb, self.lower_bb = calculate_bollinger_bands(data, 20, 2)
    self.cci = calculate_cci(data, 14)
    self.position = 0
    self.stop_loss = None
    self.take_profit = None

  def check_entry(self):
    if self.position == 0:
      if self.data['close'][-1] <= self.lower_bb[-1] and self.cci[-1] < -100:
        self.position = 1
        self.stop_loss = self.lower_bb[-1] - (2 * self.data['atr'][-1])
        self.take_profit = self.upper_bb[-1]
      elif self.data['close'][-1] >= self.upper_bb[-1] and self.cci[-1] > 100:
        self.position = -1
        self.stop_loss = self.upper_bb[-1] + (2 * self.data['atr'][-1])
        self.take_profit = self.lower_bb[-1]

  def check_exit(self):
    if self.position == 1:
      if self.data['close'][-1] <= self.stop_loss:
        self.position = 0
      elif self.data['close'][-1] >= self.take_profit:
        self.position = 0
    elif self.position == -1:
      if self.data['close'][-1] >= self.stop_loss:
        self.position = 0
      elif self.data['close'][-1] <= self.take_profit:
        self.position = 0

  def calculate_position_size(self):
    return 0.1 * self.data['equity'][-1]

